/**
 * Extracts `@handle` mentions from comment bodies and resolves them to member
 * ids.
 *
 * A handle is the local part of a member's email address, lowercased — that
 * is what the comment composer autocompletes and what `CommentService` feeds
 * to the notification fan-out, so extraction and resolution must agree
 * exactly. Mentions inside code spans and fenced blocks are ignored.
 */
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";

/** `@` must start the line or follow whitespace/punctuation, never an email. */
const MENTION_PATTERN = /(^|[\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;

function withoutCode(body: string): string {
  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
}

/** The handle Taskflow addresses a member by, derived from their email. */
export function handleOf(member: MemberWithUser): string {
  return (member.user.email.split("@")[0] ?? "").toLowerCase();
}

/** Every distinct handle mentioned, in first-appearance order. */
export function extractMentions(body: string): readonly string[] {
  const seen = new Set<string>();
  const handles: string[] = [];

  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
    const handle = (match[2] ?? "").toLowerCase();
    if (handle === "" || seen.has(handle)) continue;
    seen.add(handle);
    handles.push(handle);
  }

  return handles;
}

/**
 * Maps the mentions in `body` onto the ids of members who actually exist in
 * the organization. Unknown handles are silently dropped — a typo must never
 * fail the comment write.
 */
export function resolveMentions(
  body: string,
  members: readonly MemberWithUser[],
): readonly UserId[] {
  const byHandle = new Map<string, UserId>();
  for (const member of members) {
    byHandle.set(handleOf(member), member.userId);
  }

  const resolved: UserId[] = [];
  const seen = new Set<UserId>();
  for (const handle of extractMentions(body)) {
    const userId = byHandle.get(handle);
    if (userId === undefined || seen.has(userId)) continue;
    seen.add(userId);
    resolved.push(userId);
  }

  return resolved;
}

/** Wraps every mention in a span so the comment renderer can style it. */
export function highlightMentions(body: string): string {
  return body.replace(
    MENTION_PATTERN,
    (_match, prefix: string, handle: string) =>
      `${prefix}<span class="mention">@${handle}</span>`,
  );
}

/**
 * Pending invitations, keyed by token hash for the unauthenticated accept flow.
 */
import { and, count, desc, eq, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, invitations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvitation } from "./_mappers";
import type { CreateInvitationInput } from "@/schemas/invitation";
import type { InvitationId, IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Invitation } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export async function insertInvitation(
  orgId: OrgId,
  input: CreateInvitationInput,
  invitedBy: UserId,
  tokenHash: string,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + input.expiresInDays * MS_PER_DAY),
  );

  const row = getDb()
    .insert(invitations)
    .values({
      id: newId(),
      orgId,
      email: input.email,
      role: input.role,
      invitedBy,
      tokenHash,
      expiresAt,
      acceptedAt: null,
      revokedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvitation(row);
}

/**
 * The accept flow runs before a session exists, so this is the one read in the
 * repository layer that is not scoped by `orgId` — the token hash is the
 * credential and carries the tenant with it.
 */
export async function findInvitationByTokenHash(
  tokenHash: string,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();
  return row ? toInvitation(row) : null;
}

export async function listPendingInvitations(
  orgId: OrgId,
): Promise<readonly Invitation[]> {
  const rows = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
      ),
    )
    .orderBy(desc(invitations.createdAt))
    .all();

  return rows.map(toInvitation);
}

export async function markInvitationAccepted(
  orgId: OrgId,
  invitationId: InvitationId,
  at: IsoTimestamp,
): Promise<Invitation> {
  const row = getDb()
    .update(invitations)
    .set({ acceptedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Invitation ${invitationId} not found`);
  return toInvitation(row);
}

export async function revokeInvitation(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(invitations)
    .set({ revokedAt: stamp, updatedAt: stamp })
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Invitation ${invitationId} not found`);
  return toInvitation(row);
}

/** Pending invites hold a seat, so the seat quota counts them. */
export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

