1	/**
2	 * Fan-out honours preferences and the digest flag.
3	 *
4	 * Owner C implements `@/server/services/notification-service`.
5	 */
6	import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
7	
8	vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
9	vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
10	
11	import { emit } from "@/lib/event-bus";
12	import { TenantScopeError } from "@/lib/tenant";
13	import * as issueService from "@/server/services/issue-service";
14	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
15	import {
16	  listNotifications,
17	  notify,
18	  resolveChannels,
19	} from "@/server/services/notification-service";
20	import {
21	  createTenant,
22	  issueInput,
23	  useTemporaryDatabase,
24	} from "../server/_support/fixtures";
25	import type { Tenant } from "../server/_support/fixtures";
26	import type { CommentId } from "@/types/common";
27	import type { FlagContext } from "@/types/feature-flag";
28	
29	let cleanup: () => void;
30	let tenant: Tenant;
31	
32	beforeAll(async () => {
33	  cleanup = await useTemporaryDatabase();
34	  tenant = await createTenant("notify", "growth");
35	});
36	
37	afterAll(() => {
38	  cleanup();
39	});
40	
41	describe("services/notification-service", () => {
42	  // comment.created with mentions produces one comment_mention per mentioned user.
43	  it("creates one notification per mentioned user", async () => {
44	    const issue = await issueService.createIssue(
45	      tenant.actors.member,
46	      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions issue" }),
47	    );
48	
49	    await emit("comment.created", {
50	      orgId: tenant.org.id,
51	      actorId: tenant.userIds.member,
52	      occurredAt: issue.createdAt,
53	      commentId: "cmt-mentions-1" as CommentId,
54	      issueId: issue.id,
55	      mentionedUserIds: [tenant.userIds.admin, tenant.userIds.viewer],
56	    });
57	
58	    const forAdmin = await listNotifications(tenant.actors.owner, {
59	      orgId: tenant.org.id,
60	      recipientId: tenant.userIds.admin,
61	      unreadOnly: false,
62	      kind: ["comment_mention"],
63	      limit: 25,
64	      cursor: null,
65	    });
66	    const forViewer = await listNotifications(tenant.actors.owner, {
67	      orgId: tenant.org.id,
68	      recipientId: tenant.userIds.viewer,
69	      unreadOnly: false,
70	      kind: ["comment_mention"],
71	      limit: 25,
72	      cursor: null,
73	    });
74	
75	    expect(forAdmin.items).toHaveLength(1);
76	    expect(forViewer.items).toHaveLength(1);
77	    expect(forAdmin.items[0]?.kind).toBe("comment_mention");
78	  });
79	
80	  // The actor who caused the event is not notified about their own action.
81	  it("does not notify the actor about their own action", async () => {
82	    const rows = await notify(
83	      tenant.org.id,
84	      "comment_created",
85	      [tenant.userIds.member, tenant.userIds.admin],
86	      {
87	        title: "New comment",
88	        body: "Someone commented",
89	        href: "/issues/x",
90	        actorId: tenant.userIds.member,
91	      },
92	    );
93	
94	    expect(rows).toHaveLength(1);
95	    expect(rows[0]?.recipientId).toBe(tenant.userIds.admin);
96	  });
97	
98	  // NotificationPreference.email === false suppresses the email channel only.
99	  it("honours the per-kind email preference", async () => {
100	    await preferenceRepo.upsertPreference({
101	      orgId: tenant.org.id,
102	      userId: tenant.userIds.admin,
103	      kind: "issue_assigned",
104	      inApp: true,
105	      email: false,
106	      digestOnly: false,
107	    });
108	
109	    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
110	      title: "Assigned",
111	      body: "You were assigned",
112	      href: "/issues/y",
113	      actorId: null,
114	    });
115	
116	    expect(rows).toHaveLength(1);
117	    expect(rows[0]?.channels).toEqual(["in_app"]);
118	  });
119	
120	  // digestOnly routes the entry to the digest instead of an immediate email.
121	  it("queues a digestOnly notification for the digest instead of sending", () => {
122	    const flagsWithDigest: FlagContext = {
123	      orgId: tenant.org.id,
124	      userId: null,
125	      plan: "growth",
126	      role: null,
127	      overrides: undefined,
128	    };
129	
130	    const channels = resolveChannels(
131	      {
132	        orgId: tenant.org.id,
133	        userId: tenant.userIds.admin,
134	        kind: "digest_ready",
135	        inApp: true,
136	        email: true,
137	        digestOnly: true,
138	      },
139	      flagsWithDigest,
140	    );
141	
142	    // The org's plan includes the digest_email flag, so the entry is still
143	    // routed to the "email" channel — it will go out with the digest run
144	    // rather than never leaving the in-app row.
145	    expect(channels).toEqual(["in_app", "email"]);
146	  });
147	
148	  // isEnabled("digest_email", …) gates the digest channel by plan.
149	  it("skips the digest channel when the digest_email flag is off", () => {
150	    const flagsWithoutDigest: FlagContext = {
