/**
 * Out-of-office windows and the delegate an absent member's assignments and
 * alerts redirect to. One row per (org, user) — setting an absence again
 * replaces it via upsert.
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, memberAbsences } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toMemberAbsence } from "./_mappers";
import type { SetAbsenceInput } from "@/schemas/member";
import type { OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

export async function setAbsence(
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(memberAbsences)
    .values({
      id: newId(),
      orgId: input.orgId,
      userId: input.userId,
      delegateUserId: input.delegateUserId,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: input.note,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: input.delegateUserId,
        startsAt: input.startsAt,
        endsAt: input.endsAt,
        note: input.note,
        updatedAt: stamp,
      },
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

export async function clearAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/**
 * Drops the delegate wherever a removed member covered for someone. The
 * absence itself is left in place, now without a delegate.
 */
export async function clearDelegateFor(
  orgId: OrgId,
  delegateUserId: UserId,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}

