  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  // A removed member's own absence goes with them, and anyone who had named
  // them as a delegate is left without one rather than pointed at someone gone.
  await absenceRepo.clearAbsence(input.orgId, removed.userId);
  await absenceRepo.clearDelegateFor(input.orgId, removed.userId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

/**
 * Sets, clears or reads a member's out-of-office window. Setting again
 * replaces whatever was stored; the target and (when given) the delegate must
 * both be active members of the org, and a member may not delegate to
 * themselves. Anyone may act on their own absence — acting on someone else's
 * needs the same right as changing their role.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  if (actor.userId !== input.userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  if (new Date(input.endsAt).getTime() <= new Date(input.startsAt).getTime()) {
    throw new Error("An absence must end after it starts");
  }

  if (input.delegateUserId !== null) {
    if (input.delegateUserId === input.userId) {
      throw new Error("A member cannot delegate to themselves");
    }
    await requireActiveMember(input.orgId, input.delegateUserId);
  }

  return absenceRepo.setAbsence(input);
}

export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  if (actor.userId !== userId) {
    assertCan(actor, "member:update_role", memberResource(member));
  }

  await absenceRepo.clearAbsence(orgId, userId);
}

/**
 * Resolves to the stored absence as long as it has not ended yet — a
 * scheduled absence that has not started is still returned — and to `null`
 * once it has ended or none is set. Any member may look up any other.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  await requireActiveMember(orgId, userId);

  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (!absence) return null;
  return new Date(absence.endsAt).getTime() <= Date.now() ? null : absence;
}

/**
 * The delegate covering for `userId` at instant `at`, or `null` when they are
 * present, have no delegate, or their absence has not started / has already
 * ended. Never chases a delegate's own delegate — redirection is one level.
 */
export async function resolveActiveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (!absence || absence.delegateUserId === null) return null;

  const now = at.getTime();
  if (now < new Date(absence.startsAt).getTime()) return null;
  if (now >= new Date(absence.endsAt).getTime()) return null;

  return absence.delegateUserId;
}

async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

