subscribe("issue.overdue", async (payload) => {
  if (payload.assigneeId === null) return;

  // Redirect the alert to the delegate covering for an away assignee — the
  // issue itself stays theirs, only the overdue alert moves.
  const delegate = await resolveActiveDelegate(
    payload.orgId,
    payload.assigneeId,
    new Date(payload.occurredAt),
  );
  const recipientId = delegate ?? payload.assigneeId;

  await notify(payload.orgId, "issue_overdue", [recipientId], {
    title: "An issue is overdue",
    body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
    href: `/issues/${payload.issueId}`,
    actorId: null,
  });
});

subscribe("comment.created", async (payload) => {
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  const watchers = issue
    ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
    : [];

  await notify(payload.orgId, "comment_created", watchers, {
    title: "New comment",
    body: `A comment was added to issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });

  if (payload.mentionedUserIds.length > 0) {
    // A mention alerts both the mentioned member and, if they're away, their
    // delegate. `notify()` dedupes recipients, so a delegate who is also
    // mentioned directly still gets exactly one alert.
    const delegates = await Promise.all(
      payload.mentionedUserIds.map((userId) =>
        resolveActiveDelegate(payload.orgId, userId, new Date(payload.occurredAt)),
      ),
    );
    const recipients = [
      ...payload.mentionedUserIds,
      ...delegates.filter((id): id is UserId => id !== null),
    ];

    await notify(payload.orgId, "comment_mention", recipients, {
      title: "You were mentioned",
      body: `You were mentioned on issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  }
});

