import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { NotFoundError } from "@/server/services/_support";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("absence-verify", "growth");
});

afterAll(() => {
  cleanup();
});

const PAST = new Date(Date.now() - 60_000).toISOString();
const NOW_PLUS_1H = new Date(Date.now() + 3_600_000).toISOString();
const NOW_PLUS_2H = new Date(Date.now() + 7_200_000).toISOString();

describe("absence verify", () => {
  it("sets, reads, and clears an absence; rejects end<=start", async () => {
    const absence = await memberService.setAbsence(tenant.actors.member, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: PAST,
      endsAt: NOW_PLUS_1H,
      note: "vacation",
    });
    expect(absence.delegateUserId).toBe(tenant.userIds.admin);

    const read = await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    expect(read).toMatchObject({ delegateUserId: tenant.userIds.admin });

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: NOW_PLUS_1H,
        endsAt: PAST,
        note: null,
      }),
    ).rejects.toThrow(/end/i);

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    expect(await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member)).toBeNull();
  });

  it("refuses self-delegation, non-member delegate, and cross-tenant orgId", async () => {
    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: tenant.userIds.member,
        startsAt: PAST,
        endsAt: NOW_PLUS_1H,
        note: null,
      }),
    ).rejects.toThrow(/themselves/);

    const other = await createTenant("absence-verify-other", "growth");
    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: other.userIds.admin,
        startsAt: PAST,
        endsAt: NOW_PLUS_1H,
        note: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: other.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: PAST,
        endsAt: NOW_PLUS_1H,
        note: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("refuses setting someone else's absence without member:update_role, allows admin", async () => {
    await expect(
      memberService.setAbsence(tenant.actors.viewer, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: PAST,
        endsAt: NOW_PLUS_1H,
        note: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      memberService.setAbsence(tenant.actors.admin, {
        orgId: tenant.org.id,
        userId: tenant.userIds.member,
        delegateUserId: null,
        startsAt: PAST,
        endsAt: NOW_PLUS_1H,
        note: null,
      }),
    ).resolves.toMatchObject({ userId: tenant.userIds.member });

    await memberService.clearAbsence(tenant.actors.admin, tenant.org.id, tenant.userIds.member);
  });

  it("redirects a new assignment to the delegate, but not on self-assign", async () => {
    await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: PAST,
      endsAt: NOW_PLUS_2H,
      note: null,
    });

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Redirect on create", assigneeId: tenant.userIds.member }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.admin);

    const reassigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    expect(reassigned.assigneeId).toBe(tenant.userIds.admin);

    // Self-assign: the away member takes it themselves — no redirect.
    const selfAssigned = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });
    expect(selfAssigned.assigneeId).toBe(tenant.userIds.member);

    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
  });

  it("removeMember drops the removed member's absence and their delegations", async () => {
    const t = await createTenant("absence-verify-remove", "growth");
    await memberService.setAbsence(t.actors.owner, {
      orgId: t.org.id,
      userId: t.userIds.viewer,
      delegateUserId: t.userIds.admin,
      startsAt: PAST,
      endsAt: NOW_PLUS_2H,
      note: null,
    });
    await memberService.setAbsence(t.actors.owner, {
      orgId: t.org.id,
      userId: t.userIds.member,
      delegateUserId: t.userIds.admin,
      startsAt: PAST,
      endsAt: NOW_PLUS_2H,
      note: null,
    });

    const adminMember = await memberRepo.findMember(t.org.id, t.userIds.admin);
